  if (opts.scope === 'by_id') {
    const confirmed = posts.find((post) => Number(post.id) === Number(opts.postId || vk.post_id));
    if (confirmed && confirmed.id != null) return markPublished(pkg, opts.groupId, confirmed.id, now);
