  vk.lock_token = opts.lockToken || ('lk' + fnvHex(String(pkg.request_id) + '\n' + now + '\n' + vk.lock_seq));
  vk.locked_at = now;
  vk.status = 'locked';
  vk.retryable = false;
  vk.error_code = null;
  vk.error_message = null;
  return Object.assign(resultOf(pkg, 'publish'), { message: null });
}

function prepareGetUploadServer(pkg, options) {
