  const problem = imageLimitError(data);
  if (problem) return { ok: false, errors: [problem] };
  const size = readImageSize(data);
  return {
    ok: true,
    errors: [],
    image: {
      filename: filename || size.filename,
      mime: size.mime,
      base64: data.toString('base64'),
      byte_length: data.length,
      width: size.width,
      height: size.height,
      sha256: fnvHex(data)
    },
    bytes: data
  };
}

