  }
  const host = parsed.hostname.toLowerCase();
  const allowed = parsed.protocol === 'https:' && (
    host === 'vk.ru' || host === 'vk.com' || host.endsWith('.vk.ru') || host.endsWith('.vk.com') || host.endsWith('.userapi.com')
