function sniffImage(bytes) {
  const data = Buffer.isBuffer(bytes) ? bytes : Buffer.from(bytes || []);
  if (data.length < 8) return null;
  if (data[0] === 0xff && data[1] === 0xd8 && data[2] === 0xff) {
